        }

        public static byte[] GetStadiumGoalWav()
        {
            lock (_lock)
            {
                if (_cachedStadiumGoalWav != null) return _cachedStadiumGoalWav;
                _cachedStadiumGoalWav = GenerateStadiumGoalWav();
