            _txtPlayerBadge = new TextBlock
            {
                Text = " • 🟢 Spotify",
                FontSize = 9.5,
                FontWeight = FontWeights.Medium,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(56, 189, 248)),
