                var devirHeader = new Border
                {
                    Background = new SolidColorBrush(isLight 
                        ? System.Windows.Media.Color.FromArgb(240, 240, 249, 255) 
                        : System.Windows.Media.Color.FromArgb(220, 15, 23, 42)),
                    BorderBrush = new SolidColorBrush(isLight 
                        ? System.Windows.Media.Color.FromRgb(186, 230, 253) 
                        : System.Windows.Media.Color.FromArgb(140, 14, 165, 233)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(8),
                    Padding = new Thickness(8, 7, 8, 7),
                    Margin = new Thickness(0, 0, 0, 8)
                };
                var devirText = new TextBlock
                {
                    Text = string.Format("🕒 {0} · Devralacak Kadro ({1} {2})", commonHours ?? ("Saat " + handoverTime), targetDateStr, shiftName),
                    FontSize = 11.8,
                    FontWeight = FontWeights.SemiBold,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    Foreground = new SolidColorBrush(isLight 
                        ? System.Windows.Media.Color.FromRgb(3, 105, 161) 
                        : System.Windows.Media.Color.FromRgb(240, 249, 255)),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis
                };
                devirHeader.Child = devirText;
                _listPanel.Children.Add(devirHeader);
            }
            else // _selectedTab == 1 (Sabah), 2 (Akşam), 3 (Gece)
            {
                string tabNameStr;
                if (_selectedTab == 1) { displayList = _currentResult.Morning; commonHours = "07:00 - 15:00"; tabNameStr = "Sabah"; }
                else if (_selectedTab == 2) { displayList = _currentResult.Evening; commonHours = "15:00 - 23:00"; tabNameStr = "Akşam"; }
                else { displayList = _currentResult.Night; commonHours = "23:00 - 07:00"; tabNameStr = "Gece"; }

                var tabHeader = new Border
                {
                    Background = new SolidColorBrush(isLight 
                        ? System.Windows.Media.Color.FromArgb(240, 240, 249, 255) 
                        : System.Windows.Media.Color.FromArgb(220, 15, 23, 42)),
                    BorderBrush = new SolidColorBrush(isLight 
                        ? System.Windows.Media.Color.FromRgb(186, 230, 253) 
                        : System.Windows.Media.Color.FromArgb(140, 14, 165, 233)),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(8),
                    Padding = new Thickness(8, 7, 8, 7),
                    Margin = new Thickness(0, 0, 0, 8)
                };
                var tabHeaderText = new TextBlock
                {
                    Text = string.Format("🕒 {0} · {1} Vardiyası Kadrosu", commonHours, tabNameStr),
                    FontSize = 11.8,
                    FontWeight = FontWeights.SemiBold,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    Foreground = new SolidColorBrush(isLight 
                        ? System.Windows.Media.Color.FromRgb(3, 105, 161) 
                        : System.Windows.Media.Color.FromRgb(240, 249, 255)),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis
                };
                tabHeader.Child = tabHeaderText;
                _listPanel.Children.Add(tabHeader);
            }

            if (displayList == null || displayList.Count == 0)
            {
                _listPanel.Children.Add(new TextBlock
                {
                    Text = (_selectedTab == 0) ? "Devralacak vardiyada kayıtlı nöbetçi personel bulunamadı." : "Bu vardiyada kayıtlı nöbetçi personel bulunamadı.",
                    FontSize = 12,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    Foreground = new SolidColorBrush(isLight ? System.Windows.Media.Color.FromRgb(100, 116, 139) : System.Windows.Media.Color.FromRgb(160, 174, 192)),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    Margin = new Thickness(0, 20, 0, 20)
                });
                if (_txtFooterCount != null) _txtFooterCount.Text = (_selectedTab == 0) ? "0 Personel Devralacak" : "0 Personel Kayıtlı";
                return;
            }

            if (_txtFooterCount != null)
            {
                if (_selectedTab == 0)
                {
                    _txtFooterCount.Text = string.Format("{0} Personel Devralacak", displayList.Count);
                }
                else
                {
                    _txtFooterCount.Text = string.Format("{0} Personel Kayıtlı", displayList.Count);
                }
            }
            if (_txtFooterSheet != null)
            {
                _txtFooterSheet.Text = _currentResult.SheetName ?? "ÇİZELGE";
            }

            foreach (var person in displayList)
            {
                _listPanel.Children.Add(CreatePersonCard(person, commonHours));
            }
        }

        private Border CreatePersonCard(ShiftPerson p, string commonHours = null)
        {
            bool isLight = (_cfg.Theme == "light");
            double op = _cfg.ShiftWidgetOpacity;
            byte borderAlpha = (byte)Math.Min(255, (int)(op * (isLight ? 180 : 80)));

            System.Windows.Media.Color textPrimary, textSecondary, textMuted;
            WidgetWindow.ResolveTextColors(_cfg.TextColor, isLight, out textPrimary, out textSecondary, out textMuted);

            System.Windows.Media.Brush cardBg;
            System.Windows.Media.Brush cardBorder;

            if (p.IsSupervisor)
            {
                if (isLight)
                {
                    cardBg = new SolidColorBrush(System.Windows.Media.Color.FromArgb(170, 254, 243, 199));
                    cardBorder = new SolidColorBrush(System.Windows.Media.Color.FromArgb(180, 217, 119, 6));
                }
                else
                {
                    cardBg = new SolidColorBrush(System.Windows.Media.Color.FromArgb(45, 245, 158, 11));
                    cardBorder = new SolidColorBrush(System.Windows.Media.Color.FromArgb(140, 245, 158, 11));
                }
            }
            else
            {
                cardBg = new SolidColorBrush(isLight 
                    ? System.Windows.Media.Color.FromArgb(140, 255, 255, 255) 
                    : System.Windows.Media.Color.FromArgb(20, 255, 255, 255));
                cardBorder = new SolidColorBrush(isLight
                    ? System.Windows.Media.Color.FromArgb(borderAlpha, 215, 220, 230)
                    : System.Windows.Media.Color.FromArgb(borderAlpha, 45, 50, 65));
            }

            var card = new Border
            {
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(10, 6, 10, 6),
                Margin = new Thickness(0, 2, 0, 3),
                Background = cardBg,
                BorderThickness = new Thickness(p.IsSupervisor ? 1.5 : 1),
                BorderBrush = cardBorder
            };

            var grid = new Grid();
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            string personHours = null;
            if (p.IsSupervisor)
            {
                if (p.ShiftType == "S") personHours = "07:00 - 16:00";
                else if (p.ShiftType == "NS") personHours = "08:00 - 16:00";
                else if (p.ShiftType == "A") personHours = "14:00 - 23:00";
                else if (p.ShiftType == "G") personHours = "23:00 - 07:00";
                else personHours = !string.IsNullOrEmpty(p.ShiftHours) ? p.ShiftHours : p.ShiftCode;
            }
            else if (p.IsOvertime)
            {
                personHours = "FM";
            }
            else
            {
                if (p.ShiftType == "S") personHours = "07:00 - 15:00";
                else if (p.ShiftType == "A") personHours = "15:00 - 23:00";
                else if (p.ShiftType == "G") personHours = "23:00 - 07:00";
                else personHours = !string.IsNullOrEmpty(p.ShiftHours) ? p.ShiftHours : p.ShiftCode;
            }

            bool showBadge = p.IsOvertime || (commonHours == null) || (personHours != commonHours);

            var nameStack = new StackPanel { Orientation = Orientation.Vertical, VerticalAlignment = VerticalAlignment.Center };
            string displayName = p.IsSupervisor ? ("👮 " + p.Name) : p.Name;
            var nameTxt = new TextBlock
            {
                Text = displayName,
                FontWeight = p.IsSupervisor ? FontWeights.Bold : FontWeights.SemiBold,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                FontSize = 13.2,
                Foreground = new SolidColorBrush(textPrimary),
                TextTrimming = TextTrimming.CharacterEllipsis,
                MaxWidth = showBadge ? 220 : 310
            };
            var roleTxt = new TextBlock
            {
                Text = p.Role,
                FontWeight = p.IsSupervisor ? FontWeights.SemiBold : FontWeights.Normal,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                FontSize = 11.2,
                Margin = new Thickness(0, 1, 0, 0),
                Foreground = p.IsSupervisor
                    ? new SolidColorBrush(isLight ? System.Windows.Media.Color.FromRgb(180, 83, 9) : System.Windows.Media.Color.FromRgb(251, 191, 36))
                    : new SolidColorBrush(textMuted),
                TextTrimming = TextTrimming.CharacterEllipsis,
                MaxWidth = showBadge ? 220 : 310
            };
            nameStack.Children.Add(nameTxt);
            nameStack.Children.Add(roleTxt);

            if (showBadge)
            {
                Grid.SetColumn(nameStack, 0);
                grid.Children.Add(nameStack);

                var badge = CreateShiftBadge(p.ShiftCode, p.ShiftType, p.IsOvertime, p.IsSupervisor, p.ShiftHours);
                Grid.SetColumn(badge, 1);
                grid.Children.Add(badge);
            }
            else
            {
                Grid.SetColumn(nameStack, 0);
                Grid.SetColumnSpan(nameStack, 2);
                grid.Children.Add(nameStack);
            }

            card.Child = grid;
            return card;
        }

        private Border CreateShiftBadge(string code, string type, bool isOvertime, bool isSupervisor = false, string hours = null)
        {
            bool isLight = (_cfg.Theme == "light");
            string label;
            System.Windows.Media.Color bg, border, fg;

            if (isSupervisor)
            {
                if (type == "S")
                {
                    label = "07:00 - 16:00";
                    if (isLight)
                    {
                        bg = System.Windows.Media.Color.FromArgb(40, 2, 132, 199);
                        border = System.Windows.Media.Color.FromRgb(2, 132, 199);
                        fg = System.Windows.Media.Color.FromRgb(3, 105, 161);
                    }
                    else
                    {
                        bg = System.Windows.Media.Color.FromArgb(80, 30, 64, 175);
                        border = System.Windows.Media.Color.FromRgb(59, 130, 246);
                        fg = System.Windows.Media.Color.FromRgb(191, 219, 254);
                    }
                }
                else if (type == "NS")
                {
                    label = "08:00 - 16:00";
                    if (isLight)
                    {
                        bg = System.Windows.Media.Color.FromArgb(35, 16, 185, 129);
                        border = System.Windows.Media.Color.FromRgb(16, 185, 129);
                        fg = System.Windows.Media.Color.FromRgb(4, 120, 87);
                    }
                    else
                    {
                        bg = System.Windows.Media.Color.FromArgb(70, 5, 150, 105);
                        border = System.Windows.Media.Color.FromRgb(52, 211, 153);
                        fg = System.Windows.Media.Color.FromRgb(167, 243, 208);
                    }
                }
                else if (type == "A")
                {
                    label = "14:00 - 23:00";
                    if (isLight)
                    {
                        bg = System.Windows.Media.Color.FromArgb(35, 249, 115, 22);
                        border = System.Windows.Media.Color.FromRgb(234, 88, 12);
                        fg = System.Windows.Media.Color.FromRgb(194, 65, 12);
                    }
                    else
                    {
                        bg = System.Windows.Media.Color.FromArgb(70, 194, 65, 12);
                        border = System.Windows.Media.Color.FromRgb(249, 115, 22);
                        fg = System.Windows.Media.Color.FromRgb(254, 215, 170);
                    }
                }
                else if (type == "G")
                {
                    label = "23:00 - 07:00";
                    if (isLight)
                    {
                        bg = System.Windows.Media.Color.FromArgb(35, 147, 51, 234);
                        border = System.Windows.Media.Color.FromRgb(126, 34, 206);
                        fg = System.Windows.Media.Color.FromRgb(107, 33, 168);
                    }
                    else
                    {
                        bg = System.Windows.Media.Color.FromArgb(70, 107, 33, 168);
                        border = System.Windows.Media.Color.FromRgb(168, 85, 247);
                        fg = System.Windows.Media.Color.FromRgb(233, 213, 255);
                    }
                }
                else
                {
                    label = !string.IsNullOrEmpty(hours) ? hours : code;
                    bg = System.Windows.Media.Color.FromArgb(40, 245, 158, 11);
                    border = System.Windows.Media.Color.FromRgb(217, 119, 6);
                    fg = isLight ? System.Windows.Media.Color.FromRgb(180, 83, 9) : System.Windows.Media.Color.FromRgb(254, 240, 138);
                }
            }
            else if (isOvertime)
            {
                if (type == "S") label = "FM (07-15)";
                else if (type == "A") label = "FM (15-23)";
                else if (type == "G") label = "FM (23-07)";
                else label = "FM (" + code + ")";

                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(40, 245, 158, 11);
                    border = System.Windows.Media.Color.FromRgb(217, 119, 6);
                    fg = System.Windows.Media.Color.FromRgb(180, 83, 9);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(90, 217, 119, 6);
                    border = System.Windows.Media.Color.FromRgb(250, 204, 21);
                    fg = System.Windows.Media.Color.FromRgb(254, 240, 138);
                }
            }
            else if (type == "S")
            {
                label = "07:00 - 15:00";
                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(35, 14, 165, 233);
                    border = System.Windows.Media.Color.FromRgb(2, 132, 199);
                    fg = System.Windows.Media.Color.FromRgb(3, 105, 161);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(70, 30, 64, 175);
                    border = System.Windows.Media.Color.FromRgb(59, 130, 246);
                    fg = System.Windows.Media.Color.FromRgb(191, 219, 254);
                }
            }
            else if (type == "A")
            {
                label = "15:00 - 23:00";
                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(35, 249, 115, 22);
                    border = System.Windows.Media.Color.FromRgb(234, 88, 12);
                    fg = System.Windows.Media.Color.FromRgb(194, 65, 12);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(70, 194, 65, 12);
                    border = System.Windows.Media.Color.FromRgb(249, 115, 22);
                    fg = System.Windows.Media.Color.FromRgb(254, 215, 170);
                }
            }
            else if (type == "G")
            {
                label = "23:00 - 07:00";
                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(35, 147, 51, 234);
                    border = System.Windows.Media.Color.FromRgb(126, 34, 206);
                    fg = System.Windows.Media.Color.FromRgb(107, 33, 168);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(70, 107, 33, 168);
                    border = System.Windows.Media.Color.FromRgb(168, 85, 247);
                    fg = System.Windows.Media.Color.FromRgb(233, 213, 255);
                }
            }
            else
            {
                label = code;
                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(30, 0, 0, 0);
                    border = System.Windows.Media.Color.FromArgb(60, 0, 0, 0);
                    fg = System.Windows.Media.Color.FromRgb(15, 23, 42);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(40, 255, 255, 255);
                    border = System.Windows.Media.Color.FromArgb(80, 255, 255, 255);
                    fg = System.Windows.Media.Brushes.White.Color;
                }
            }

            return new Border
            {
                CornerRadius = new CornerRadius(6),
                Padding = new Thickness(8, 3, 8, 3),
                VerticalAlignment = VerticalAlignment.Center,
                Background = new SolidColorBrush(bg),
                BorderThickness = new Thickness(1),
                BorderBrush = new SolidColorBrush(border),
                Child = new TextBlock
                {
                    Text = label,
                    FontSize = 10.8,
                    FontWeight = (isOvertime || isSupervisor) ? FontWeights.Bold : FontWeights.SemiBold,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    Foreground = new SolidColorBrush(fg)
                }
            };
        }

        private void RenderStationListTab()
        {
            bool isLight = (_cfg.Theme == "light");
            System.Windows.Media.Color textPrimary, textSecondary, textMuted;
            WidgetWindow.ResolveTextColors(_cfg.TextColor, isLight, out textPrimary, out textSecondary, out textMuted);

            if (_currentResult == null || _currentResult.StationResult == null || _currentResult.StationResult.Stations == null || _currentResult.StationResult.Stations.Count == 0)
            {
                if (string.IsNullOrEmpty(_cfg.SupervisorFolderPath))
                {
                    var noSupStack = new StackPanel
                    {
                        Orientation = Orientation.Vertical,
                        HorizontalAlignment = HorizontalAlignment.Center,
                        Margin = new Thickness(10, 16, 10, 16)
                    };
                    noSupStack.Children.Add(new TextBlock
                    {
                        Text = "Vardiya Amirliği & İstasyon Çizelgesi Seçilmedi",
                        FontWeight = FontWeights.Bold,
                        FontSize = 12,
                        FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                        Foreground = new SolidColorBrush(isLight ? System.Windows.Media.Color.FromRgb(30, 41, 59) : System.Windows.Media.Brushes.White.Color),
                        HorizontalAlignment = HorizontalAlignment.Center,
                        Margin = new Thickness(0, 0, 0, 8)
                    });
                    var btnSupPick = new Border
                    {
                        CornerRadius = new CornerRadius(8),
                        Background = new SolidColorBrush(isLight ? System.Windows.Media.Color.FromRgb(2, 132, 199) : System.Windows.Media.Color.FromRgb(0, 229, 255)),
                        Padding = new Thickness(14, 7, 14, 7),
                        HorizontalAlignment = HorizontalAlignment.Center,
                        Cursor = Cursors.Hand,
                        Child = new TextBlock
                        {
                            Text = "📁 İstasyon Çizelgesini Seç...",
                            FontSize = 11,
                            FontWeight = FontWeights.SemiBold,
                            Foreground = System.Windows.Media.Brushes.White
                        }
                    };
                    btnSupPick.MouseLeftButtonUp += delegate
                    {
                        string chosen = ShellLinkHelper.PromptPickShortcutOrFile(_cfg.SupervisorFolderPath);
                        if (string.IsNullOrEmpty(chosen)) chosen = ShellLinkHelper.PromptPickFolder(_cfg.SupervisorFolderPath);
                        if (!string.IsNullOrEmpty(chosen))
                        {
                            _cfg.SupervisorFolderPath = chosen;
                            _cfg.Save();
                            LoadScheduleAsync(true);
                        }
                    };
                    noSupStack.Children.Add(btnSupPick);
                    _listPanel.Children.Add(noSupStack);
                    return;
                }

                _listPanel.Children.Add(new TextBlock
                {
                    Text = "İstasyon çizelgesi bulunamadı veya henüz yüklenmedi.",
                    FontSize = 12,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    Foreground = new SolidColorBrush(isLight ? System.Windows.Media.Color.FromRgb(100, 116, 139) : System.Windows.Media.Color.FromRgb(160, 174, 192)),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    Margin = new Thickness(0, 20, 0, 20)
                });
                return;
            }

            var stResult = _currentResult.StationResult;
            DateTime now = DateTime.Now;
            string curShiftName, curShiftHours, curShiftCode, nextShiftName, nextShiftHours, nextShiftTime;
            ShiftScheduleService.GetStationShiftContext(now, out curShiftName, out curShiftHours, out curShiftCode, out nextShiftName, out nextShiftHours, out nextShiftTime);

            // Alt Filtre Butonları
            var filterGrid = new Grid { Margin = new Thickness(0, 0, 0, 8) };
            for (int f = 0; f < 4; f++) filterGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            filterGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            string[] filterTitles = new string[] { "Anlık", "Sabah (07-16)", "Akşam (16-24)", "Tümü" };
            for (int f = 0; f < 4; f++)
            {
                int fIdx = f;
                bool isSel = (_stationFilterMode == f);
                var fText = new TextBlock
                {
                    Text = filterTitles[f],
                    FontSize = 10.5,
                    FontWeight = isSel ? FontWeights.Bold : FontWeights.Normal,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    Foreground = isSel ? System.Windows.Media.Brushes.White : new SolidColorBrush(textSecondary),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                };
                var fBorder = new Border
                {
                    CornerRadius = new CornerRadius(6),
                    Padding = new Thickness(2, 4, 2, 4),
                    Margin = new Thickness(f == 0 ? 0 : 2, 0, 2, 0),
                    Cursor = Cursors.Hand,
                    Background = isSel ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(2, 132, 199)) : System.Windows.Media.Brushes.Transparent,
                    BorderBrush = isSel ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(56, 189, 248)) : System.Windows.Media.Brushes.Transparent,
                    BorderThickness = new Thickness(isSel ? 1 : 0),
                    Child = fText
                };
                fBorder.MouseLeftButtonUp += delegate(object s, MouseButtonEventArgs e)
                {
                    e.Handled = true;
                    _stationFilterMode = fIdx;
                    RenderStaffList();
                };
                Grid.SetColumn(fBorder, f);
                filterGrid.Children.Add(fBorder);
            }

            // Ayrı Pencere Açma Butonu
            var btnPopout = new Border
            {
                CornerRadius = new CornerRadius(6),
                Padding = new Thickness(5, 3, 5, 3),
                Margin = new Thickness(2, 0, 0, 0),
                Cursor = Cursors.Hand,
                ToolTip = "İstasyon Çizelgesini Ayrı Masaüstü Widget'ı Olarak Aç",
                Background = new SolidColorBrush(isLight ? System.Windows.Media.Color.FromArgb(20, 0, 0, 0) : System.Windows.Media.Color.FromArgb(30, 255, 255, 255)),
                Child = new TextBlock
                {
                    Text = "↗ Ayrı Aç",
                    FontSize = 10.0,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(isLight ? System.Windows.Media.Color.FromRgb(2, 132, 199) : System.Windows.Media.Color.FromRgb(56, 189, 248)),
                    VerticalAlignment = VerticalAlignment.Center
                }
            };
            btnPopout.MouseLeftButtonUp += delegate(object s, MouseButtonEventArgs e)
            {
                e.Handled = true;
                _cfg.ShowStationWidget = true;
                _cfg.Save();
                if (OnOpenStationWidgetRequested != null) OnOpenStationWidgetRequested();
            };
            Grid.SetColumn(btnPopout, 4);
            filterGrid.Children.Add(btnPopout);
            _listPanel.Children.Add(filterGrid);

            // Aktif Vardiya Başlık Şeridi
            string headerText;
            if (_stationFilterMode == 0)
            {
                if (curShiftCode == "S") headerText = "🟢 07:00 - 16:00 · Şu An Sabah İstasyon Nöbeti Görevde";
                else if (curShiftCode == "A") headerText = "🟢 16:00 - 24:00 · Şu An Akşam İstasyon Nöbeti Görevde";
                else headerText = "🌙 İstasyonlar Gece Yolcuya Kapalı (Sabah Nöbeti 07:00'de Başlar)";
            }
            else if (_stationFilterMode == 1)
            {
                headerText = "☀️ 07:00 - 16:00 · Sabah İstasyon Nöbetçileri";
            }
            else if (_stationFilterMode == 2)
            {
                headerText = "🌙 16:00 - 24:00 · Akşam İstasyon Nöbetçileri";
            }
            else
            {
                headerText = "📋 Sabah & Akşam Tüm İstasyon Kadrosu";
            }

            var stHeader = new Border
            {
                Background = new SolidColorBrush(isLight 
                    ? System.Windows.Media.Color.FromArgb(240, 240, 249, 255) 
                    : System.Windows.Media.Color.FromArgb(220, 15, 23, 42)),
                BorderBrush = new SolidColorBrush(isLight 
                    ? System.Windows.Media.Color.FromRgb(186, 230, 253) 
                    : System.Windows.Media.Color.FromArgb(140, 14, 165, 233)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(8, 6, 8, 6),
                Margin = new Thickness(0, 0, 0, 7)
            };
            stHeader.Child = new TextBlock
            {
                Text = headerText,
                FontSize = 11.5,
                FontWeight = FontWeights.SemiBold,
                FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                Foreground = new SolidColorBrush(isLight 
                    ? System.Windows.Media.Color.FromRgb(3, 105, 161) 
                    : System.Windows.Media.Color.FromRgb(240, 249, 255)),
                HorizontalAlignment = HorizontalAlignment.Center,
                TextTrimming = TextTrimming.CharacterEllipsis
            };
            _listPanel.Children.Add(stHeader);

            if (_scrollViewer != null) _scrollViewer.MaxHeight = 850;

            // İstasyon kartlarını gruplayarak listele (Aynı gruptaki ve aynı personeldeki istasyonlar tek kartta, isim tam ortada)
            int stIdx = 0;
            while (stIdx < stResult.Stations.Count)
            {
                var grpList = new List<StationDutyItem>();
                var firstItem = stResult.Stations[stIdx];
                grpList.Add(firstItem);
                stIdx++;

                while (stIdx < stResult.Stations.Count &&
                       stResult.Stations[stIdx].GroupId == firstItem.GroupId &&
                       (stResult.Stations[stIdx].MorningName ?? "") == (firstItem.MorningName ?? "") &&
                       (stResult.Stations[stIdx].EveningName ?? "") == (firstItem.EveningName ?? ""))
                {
                    grpList.Add(stResult.Stations[stIdx]);
                    stIdx++;
                }

                _listPanel.Children.Add(CreateStationGroupCard(grpList, _stationFilterMode, curShiftCode));
            }

            if (_txtFooterCount != null)
            {
                _txtFooterCount.Text = string.Format("{0} İstasyon (Üsküdar ➔ Sultanbeyli)", stResult.Stations.Count);
            }
            if (_txtFooterSheet != null)
            {
                _txtFooterSheet.Text = !string.IsNullOrEmpty(stResult.SheetName) ? stResult.SheetName : "EKİM 2026";
            }
        }

        private Border CreateStationGroupCard(List<StationDutyItem> groupItems, int filterMode, string curShiftCode)
        {
            var item = groupItems[0];
            bool isLight = (_cfg.Theme == "light");
            System.Windows.Media.Color textPrimary, textSecondary, textMuted;
            WidgetWindow.ResolveTextColors(_cfg.TextColor, isLight, out textPrimary, out textSecondary, out textMuted);

            System.Windows.Media.Color grpColor = ShiftScheduleService.GetStationGroupColor(item.GroupId);

            var card = new Border
            {
                CornerRadius = new CornerRadius(6),
                Padding = new Thickness(6, 2.5, 8, 2.5),
                Margin = new Thickness(0, 1, 0, 1.5),
                Background = new SolidColorBrush(System.Windows.Media.Color.FromArgb((byte)(isLight ? 42 : 36), grpColor.R, grpColor.G, grpColor.B)),
                BorderThickness = new Thickness(3, 1, 1, 1),
                BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromArgb((byte)(isLight ? 175 : 145), grpColor.R, grpColor.G, grpColor.B))
            };

            bool showBoth = (filterMode == 3);
            string activeName = null;

            if (!showBoth)
            {
                bool useMorning = (filterMode == 1) || (filterMode == 0 && curShiftCode != "A");
                activeName = useMorning ? item.MorningName : item.EveningName;
            }

            var rowGrid = new Grid();
            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            // Sol taraf: Gruptaki istasyonları alt alta diz (07 Ümraniye, 08 Çarşı...)
            var stationsStack = new StackPanel
            {
                Orientation = Orientation.Vertical,
                VerticalAlignment = VerticalAlignment.Center
            };

            for (int i = 0; i < groupItems.Count; i++)
            {
                var st = groupItems[i];
                var stRow = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, i == 0 ? 0 : 2, 0, 0)
                };

                var idxBorder = new Border
                {
                    Width = 18,
                    Height = 18,
                    CornerRadius = new CornerRadius(9),
                    Background = new SolidColorBrush(System.Windows.Media.Color.FromArgb((byte)(isLight ? 55 : 65), grpColor.R, grpColor.G, grpColor.B)),
                    BorderBrush = new SolidColorBrush(grpColor),
                    BorderThickness = new Thickness(1),
                    Margin = new Thickness(0, 0, 6, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                idxBorder.Child = new TextBlock
                {
                    Text = st.Order.ToString("D2"),
                    FontSize = 9.0,
                    FontWeight = FontWeights.Bold,
                    Foreground = new SolidColorBrush(isLight ? grpColor : System.Windows.Media.Colors.White),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                };
                stRow.Children.Add(idxBorder);

                var stNameTxt = new TextBlock
                {
                    Text = st.DisplayName,
                    FontWeight = FontWeights.SemiBold,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    FontSize = 11.2,
                    Foreground = new SolidColorBrush(textPrimary),
                    VerticalAlignment = VerticalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxWidth = 165
                };
                stRow.Children.Add(stNameTxt);

                stationsStack.Children.Add(stRow);
            }

            Grid.SetColumn(stationsStack, 0);
            rowGrid.Children.Add(stationsStack);

            // Sağ taraf: Tek personel ismi, dikeyde tam ortada (VerticalAlignment.Center)
            if (!showBoth)
            {
                string dispStaffName = !string.IsNullOrEmpty(activeName) ? activeName : "Belirtilmedi";
                var staffTxt = new TextBlock
                {
                    Text = dispStaffName,
                    FontWeight = FontWeights.SemiBold,
                    FontFamily = new System.Windows.Media.FontFamily("Inter, Segoe UI"),
                    FontSize = 11.4,
                    Foreground = new SolidColorBrush(textPrimary),
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxWidth = 195,
                    Margin = new Thickness(6, 0, 2, 0)
                };

                Grid.SetColumn(staffTxt, 1);
                rowGrid.Children.Add(staffTxt);
            }
            else // showBoth == true (Tümü sekmesi)
            {
                var bothStack = new StackPanel
                {
                    Orientation = Orientation.Vertical,
                    VerticalAlignment = VerticalAlignment.Center,
                    HorizontalAlignment = HorizontalAlignment.Right,
                    Margin = new Thickness(6, 0, 2, 0)
                };

                string mText = string.Format("☀️ {0}", !string.IsNullOrEmpty(item.MorningName) ? item.MorningName : "Boş");
                bothStack.Children.Add(new TextBlock
                {
                    Text = mText,
                    FontSize = 10.4,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(textPrimary),
                    HorizontalAlignment = HorizontalAlignment.Right,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxWidth = 185
                });

                string eText = string.Format("🌙 {0}", !string.IsNullOrEmpty(item.EveningName) ? item.EveningName : "Boş");
                bothStack.Children.Add(new TextBlock
                {
                    Text = eText,
                    FontSize = 10.4,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = new SolidColorBrush(textPrimary),
                    HorizontalAlignment = HorizontalAlignment.Right,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    MaxWidth = 185,
                    Margin = new Thickness(0, 1, 0, 0)
                });

                Grid.SetColumn(bothStack, 1);
                rowGrid.Children.Add(bothStack);
            }

            card.Child = rowGrid;
            return card;
        }

        private Border CreateStationBadge(string code, string label, bool isLeave, bool isOvertime)
        {
            bool isLight = (_cfg.Theme == "light");
            System.Windows.Media.Color bg, border, fg;

            string badgeText;
            if (isLeave)
            {
                badgeText = !string.IsNullOrEmpty(code) ? (code + " (İzin)") : "İzinli";
                bg = System.Windows.Media.Color.FromArgb(40, 245, 158, 11);
                border = System.Windows.Media.Color.FromRgb(217, 119, 6);
                fg = isLight ? System.Windows.Media.Color.FromRgb(180, 83, 9) : System.Windows.Media.Color.FromRgb(254, 240, 138);
            }
            else if (isOvertime)
            {
                if (code == "FS" || (label != null && label.Contains("07-16")))
                {
                    badgeText = "FS 07-16";
                }
                else if (code == "FA" || (label != null && label.Contains("16-24")))
                {
                    badgeText = "FA 16-24";
                }
                else
                {
                    badgeText = !string.IsNullOrEmpty(code) ? ("FM (" + code + ")") : "FM";
                }
                bg = System.Windows.Media.Color.FromArgb(50, 234, 88, 12);
                border = System.Windows.Media.Color.FromRgb(234, 88, 12);
                fg = isLight ? System.Windows.Media.Color.FromRgb(194, 65, 12) : System.Windows.Media.Color.FromRgb(254, 215, 170);
            }
            else if (code == "S" || (label != null && label.Contains("07-16")))
            {
                badgeText = "S 07-16";
                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(35, 14, 165, 233);
                    border = System.Windows.Media.Color.FromRgb(2, 132, 199);
                    fg = System.Windows.Media.Color.FromRgb(3, 105, 161);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(70, 30, 64, 175);
                    border = System.Windows.Media.Color.FromRgb(59, 130, 246);
                    fg = System.Windows.Media.Color.FromRgb(191, 219, 254);
                }
            }
            else if (code == "A" || (label != null && label.Contains("16-24")))
            {
                badgeText = "A 16-24";
                if (isLight)
                {
                    bg = System.Windows.Media.Color.FromArgb(35, 249, 115, 22);
                    border = System.Windows.Media.Color.FromRgb(234, 88, 12);
                    fg = System.Windows.Media.Color.FromRgb(194, 65, 12);
                }
                else
                {
                    bg = System.Windows.Media.Color.FromArgb(70, 194, 65, 12);
                    border = System.Windows.Media.Color.FromRgb(249, 115, 22);
                    fg = System.Windows.Media.Color.FromRgb(254, 215, 170);
                }
            }
            else
            {
                badgeText = !string.IsNullOrEmpty(code) ? code : (!string.IsNullOrEmpty(label) ? label : "-");
                bg = System.Windows.Media.Color.FromArgb(30, 100, 116, 139);
                border = System.Windows.Media.Color.FromRgb(100, 116, 139);
                fg = isLight ? System.Windows.Media.Color.FromRgb(71, 85, 105) : System.Windows.Media.Color.FromRgb(203, 213, 225);
            }

            var b = new Border
            {
                CornerRadius = new CornerRadius(5),
                Padding = new Thickness(6, 2, 6, 2),
                Background = new SolidColorBrush(bg),
                BorderBrush = new SolidColorBrush(border),
                BorderThickness = new Thickness(1),
                VerticalAlignment = VerticalAlignment.Center
            };
            b.Child = new TextBlock
            {
                Text = badgeText,
                FontSize = 10.5,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush(fg)
            };
            return b;
        }

        private bool _isApplyingZOrder = false;
        public void ApplyZOrder()
        {
            if (_isApplyingZOrder) return;
            _isApplyingZOrder = true;
            try
            {
                IntPtr hwnd = new WindowInteropHelper(this).Handle;
                if (hwnd == IntPtr.Zero) return;

                int exStyle = Win32.GetWindowLong(hwnd, Win32.GWL_EXSTYLE);
                exStyle |= Win32.WS_EX_TOOLWINDOW | Win32.WS_EX_NOACTIVATE;
                Win32.SetWindowLong(hwnd, Win32.GWL_EXSTYLE, exStyle);

                Win32.SetWindowPos(hwnd, Win32.HWND_BOTTOM, 0, 0, 0, 0, Win32.SWP_NOMOVE | Win32.SWP_NOSIZE | Win32.SWP_NOACTIVATE);
            }
            catch { }
            finally
            {
                _isApplyingZOrder = false;
            }
        }
    }

