                    txtSupFolder.ToolTip = "Seçilen Vardiya Amiri Hedefi:\n" + _cfg.SupervisorFolderPath +
                                           (_cfg.SupervisorFolderPath.EndsWith(".lnk", StringComparison.OrdinalIgnoreCase)
