            // 3. Zen Şeffaf Hızlı Not Kartı (Sticky Pad)
            _mainContentPanel.Children.Add(CreateSectionTitle("📝 ZEN ŞEFFAF HIZLI NOT KARTI (STICKY PAD)"));

